package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*; @WebServlet("/vote") public class VoteServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("studentId")==null){s.sendRedirect(r.getContextPath()+"/?error=Login+to+upvote");return;}try{boolean ok=new CreatorDAO().vote(Integer.parseInt(r.getParameter("collabId")),(Integer)h.getAttribute("studentId"));s.sendRedirect(r.getContextPath()+"/discover?message="+(ok?"Upvote+added":"You+already+upvoted"));}catch(Exception e){s.sendRedirect(r.getContextPath()+"/discover?error=Vote+failed");}}}
